import '../../features/intelligence/domain/intelligence_library.dart';

/// Spanish wording for ORVIKA's curated offline intelligence reference.
class SpanishIntelligenceContent {
  SpanishIntelligenceContent._();

  static const Map<String, Map<String, String>> _entries = {
    'url-http': {'title':'HTTP sin cifrar','signal':'Una dirección web comienza por http:// en lugar de https://.','meaning':'La conexión no utiliza TLS para proteger los datos durante la transmisión. La información intercambiada puede quedar expuesta o ser modificada en la red.','action':'Evita introducir contraseñas o datos de pago. Accede a la organización mediante un marcador fiable o una dirección verificada de forma independiente.','limit':'HTTPS protege la conexión; no demuestra que el sitio web sea legítimo.'},
    'url-userinfo': {'title':'Información de usuario engañosa en una URL','signal':'Una URL contiene texto antes del símbolo @, por ejemplo https://trusted.example@unknown.example/.','meaning':'Los navegadores interpretan como nombre de host el texto que aparece después de @. El texto aparentemente fiable anterior puede estar diseñado para distraer.','action':'Lee el nombre de host real justo después de @ y verifica el dominio registrable antes de visitar el sitio.','limit':'La información de usuario en una URL es inusual, pero por sí sola no demuestra una intención maliciosa.'},
    'url-punycode': {'title':'Dominio internacionalizado / Punycode','signal':'Un nombre de host contiene una etiqueta xn-- o caracteres visualmente similares.','meaning':'Los nombres de dominio internacionalizados pueden utilizar caracteres de distintos sistemas de escritura que se parecen a letras latinas.','action':'Comprueba la ortografía exacta y el titular del dominio mediante una fuente fiable. No te fíes únicamente de un logotipo o nombre conocido.','limit':'Muchos sitios legítimos utilizan nombres de dominio internacionalizados.'},
    'url-subdomains': {'title':'Cadena profunda de subdominios','signal':'Un nombre de host contiene varias etiquetas, como login.account.example.invalid.','meaning':'El dominio registrado no tiene por qué ser la primera palabra conocida de la dirección. Los atacantes pueden colocar nombres de marcas en subdominios que controlan.','action':'Lee el nombre de host de derecha a izquierda e identifica el dominio registrable. Verifícalo de forma independiente.','limit':'Las cadenas largas de subdominios también tienen usos legítimos.'},
    'message-urgency': {'title':'Urgencia y presión','signal':'Un mensaje exige actuar de inmediato, amenaza con cerrar una cuenta o impone un plazo artificial.','meaning':'La presión puede desalentar la verificación independiente y empujar al destinatario a actuar sin pensar.','action':'Haz una pausa. Contacta con la organización mediante una aplicación, sitio web o número oficial que ya conozcas, no mediante los datos del mensaje.','limit':'El lenguaje urgente también puede aparecer en comunicaciones legítimas; el contexto importa.'},
    'message-credentials': {'title':'Solicitud de credenciales u OTP','signal':'Un remitente solicita una contraseña, OTP, código de recuperación o aprobación de una solicitud de inicio de sesión inesperada.','meaning':'Estos secretos o aprobaciones pueden dar acceso a una cuenta o autorizar una transacción.','action':'Nunca reveles contraseñas ni OTP. Rechaza las solicitudes de aprobación inesperadas y contacta con el servicio por su canal oficial.','limit':'Una coincidencia de palabras clave solo identifica un tema; no determina quién envió el mensaje ni su intención.'},
    'message-payment': {'title':'Pago o reembolso inesperado','signal':'Un mensaje solicita una transferencia, una tasa de gestión, una acción de reembolso o un pago para desbloquear un beneficio.','meaning':'Las instrucciones financieras inesperadas pueden utilizarse para desviar fondos o recopilar datos de pago.','action':'Verifica el beneficiario, el importe y el motivo mediante un canal fiable distinto antes de actuar.','limit':'El lenguaje relacionado con pagos también es habitual en facturas y avisos de servicio legítimos.'},
    'qr-payment': {'title':'Solicitud de pago mediante QR','signal':'Un contenido QR utiliza un esquema de pago como upi://pay.','meaning':'El escaneo puede preparar un pago a un destinatario. Un código QR no autentica al beneficiario ni garantiza que el importe sea correcto.','action':'Comprueba el nombre del beneficiario, el identificador UPI y el importe en la aplicación de pago antes de autorizar. Cancela si algo no coincide.','limit':'Un contenido de pago no es fraudulento por naturaleza; verifica los datos de la transacción.'},
    'qr-action': {'title':'Código QR con un enlace de acción','signal':'Un contenido QR incluye una acción web, telefónica, de correo electrónico, SMS o específica de una aplicación.','meaning':'El contenido puede abrir un destino o rellenar una acción cuando otra aplicación lo procesa.','action':'Examina primero el contenido decodificado. No abras enlaces desconocidos ni apruebes acciones rellenadas previamente sin verificarlas.','limit':'El tipo de contenido por sí solo no permite determinar si su origen es fiable.'},
    'account-mfa': {'title':'Aprobación MFA inesperada','signal':'Recibes una solicitud de aprobación de inicio de sesión o un código de un solo uso que no has solicitado.','meaning':'Alguien puede estar intentando iniciar sesión con el identificador y la contraseña de tu cuenta, o el código puede haberse generado por error.','action':'Rechaza la solicitud, no compartas el código, cambia la contraseña mediante el servicio oficial si procede y revisa las sesiones activas.','limit':'Una solicitud inesperada es una señal de alerta, no la confirmación de que una cuenta esté comprometida.'},
  };

  static IntelligenceEntry localize(IntelligenceEntry entry, String languageCode) {
    if (languageCode != 'es') return entry;
    final values = _entries[entry.id];
    if (values == null) return entry;
    return IntelligenceEntry(id: entry.id, title: values['title']!, category: entry.category,
      signal: values['signal']!, meaning: values['meaning']!, action: values['action']!, limit: values['limit']!);
  }
}
